<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Playground</title>
<style>
  :root {
    --bg: #0f1117;
    --panel: #1a1d27;
    --accent: #6ea8fe;
    --text: #e6e8ee;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 16px;
    background: var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  }
  h1 {
    font-size: 1.1rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    color: #9aa3b5;
    margin: 16px 0 0;
  }
  #sim {
    width: 560px;
    height: 420px;
    max-width: 95vw;
    background: var(--panel);
    border: 1px solid #2a2f3f;
    border-radius: 12px;
    box-shadow: 0 8px 32px rgba(0,0,0,0.45);
    cursor: crosshair;
    touch-action: none;
  }
  .controls {
    display: flex;
    gap: 10px;
    margin-bottom: 24px;
  }
  button {
    background: #232838;
    color: var(--text);
    border: 1px solid #333a4f;
    border-radius: 8px;
    padding: 9px 18px;
    font-size: 0.95rem;
    font-family: inherit;
    cursor: pointer;
    transition: background 0.15s, transform 0.05s;
  }
  button:hover { background: #2d3450; border-color: var(--accent); }
  button:active { transform: scale(0.96); }
  #play.paused { border-color: #f0a35e; }
  .hint { color: #6b7385; font-size: 0.85rem; margin: 0; }
</style>
</head>
<body>
  <h1>Bouncing Ball Playground</h1>
  <canvas id="sim" width="560" height="420"></canvas>
  <div class="controls">
    <button id="drop">Drop Ball</button>
    <button id="play">Pause</button>
    <button id="clear">Clear</button>
  </div>
  <p class="hint">Click the canvas to add a ball at the cursor.</p>

<script>
(function () {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  const GRAVITY = 0.35;       // per step, per unit dt
  const RESTITUTION = 0.82;   // energy kept on bounce
  const FRICTION = 0.995;     // mild air drag

  const COLORS = ['#6ea8fe', '#f56c8d', '#5ed3a8', '#f0c95e', '#b58cf5', '#5ecbe8'];
  let colorIdx = 0;

  let balls = [];
  let running = true;

  function addBall(x, y, vx = 0, vy = 0, r) {
    if (r == null) r = 8 + Math.random() * 14;
    r = Math.max(2, Math.min(r, Math.min(W, H) / 2 - 1));
    // Clamp spawn point fully inside the canvas
    x = Math.max(r, Math.min(W - r, x));
    y = Math.max(r, Math.min(H - r, y));
    const ball = { x, y, vx, vy, r, color: COLORS[colorIdx++ % COLORS.length] };
    balls.push(ball);
    draw();
    return ball;
  }

  function clear() {
    balls = [];
    draw();
  }

  function step(dt = 1) {
    // Sub-step large dt values so fast balls can't tunnel through edges
    let remaining = dt;
    while (remaining > 0) {
      const h = Math.min(remaining, 1);
      integrate(h);
      remaining -= h;
    }
    draw();
  }

  function integrate(h) {
    for (const b of balls) {
      b.vy += GRAVITY * h;
      b.vx *= Math.pow(FRICTION, h);
      b.x += b.vx * h;
      b.y += b.vy * h;

      // Floor
      if (b.y + b.r > H) {
        b.y = H - b.r;
        if (b.vy > 0) b.vy = -b.vy * RESTITUTION;
        // kill tiny jitter so balls settle
        if (Math.abs(b.vy) < GRAVITY * 1.5) b.vy = 0;
      }
      // Ceiling
      if (b.y - b.r < 0) {
        b.y = b.r;
        if (b.vy < 0) b.vy = -b.vy * RESTITUTION;
      }
      // Right wall
      if (b.x + b.r > W) {
        b.x = W - b.r;
        if (b.vx > 0) b.vx = -b.vx * RESTITUTION;
      }
      // Left wall
      if (b.x - b.r < 0) {
        b.x = b.r;
        if (b.vx < 0) b.vx = -b.vx * RESTITUTION;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    for (const b of balls) {
      const grad = ctx.createRadialGradient(
        b.x - b.r * 0.35, b.y - b.r * 0.35, b.r * 0.1,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, '#ffffff');
      grad.addColorStop(0.25, b.color);
      grad.addColorStop(1, shade(b.color));
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();
    }
  }

  function shade(hex) {
    const n = parseInt(hex.slice(1), 16);
    const r = (n >> 16) & 255, g = (n >> 8) & 255, bl = n & 255;
    return `rgb(${r * 0.45 | 0}, ${g * 0.45 | 0}, ${bl * 0.45 | 0})`;
  }

  // --- UI wiring ---
  canvas.addEventListener('pointerdown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (W / rect.width);
    const y = (e.clientY - rect.top) * (H / rect.height);
    addBall(x, y, (Math.random() - 0.5) * 6, -Math.random() * 3);
  });

  document.getElementById('drop').addEventListener('click', () => {
    addBall(
      W * (0.2 + Math.random() * 0.6),
      H * 0.15,
      (Math.random() - 0.5) * 5,
      0
    );
  });

  const playBtn = document.getElementById('play');
  playBtn.addEventListener('click', () => {
    running = !running;
    playBtn.textContent = running ? 'Pause' : 'Play';
    playBtn.classList.toggle('paused', !running);
  });

  document.getElementById('clear').addEventListener('click', clear);

  function frame() {
    if (running) step(1);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  draw();

  // --- Programmatic API ---
  window.sim = {
    w: W,
    h: H,
    balls: () => balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r })),
    addBall,
    clear,
    step,
  };
})();
</script>
</body>
</html>
